import os
import firebase_admin
from firebase_admin import auth, credentials

def start_password_reset_flow(email: str) -> str:
    """
    Starts the password reset flow for a local email/password account
    using the Firebase Authentication Admin SDK.
    """
    if not firebase_admin._apps:
        service_account_path = os.environ.get("FIREBASE_SERVICE_ACCOUNT_PATH")
        if service_account_path:
            firebase_admin.initialize_app(credentials.Certificate(service_account_path))
        else:
            firebase_admin.initialize_app()

    try:
        # Generates the out-of-band (OOB) code link required to reset the password.
        # This link must be sent to the user's email to complete the account lifecycle flow.
        reset_link = auth.generate_password_reset_link(email)
        return reset_link
    except auth.EmailNotFoundError:
        raise ValueError(f"No local account exists for the email address: {email}")
    except firebase_admin.exceptions.FirebaseError as e:
        raise RuntimeError(f"Failed to start password reset flow for {email}: {e}")
